evidence.en:
const seen = [];

function isDuplicate(x) {
  return seen.some((v) => v === x);   // equality check
}

function record(x) {
  if (!isDuplicate(x)) seen.push(x);
}

record(NaN);
record(NaN);
console.log(seen.length);   // 2 — the "duplicate" got in

